from проверка_лицензий import main

class TestCheckLicense(unittest.TestCase):
    def test_main_runs_without_error(self):
        # Проверяем, что main() выполняется без исключений
        try:
            main()
        except Exception as e:
            self.fail(f"main() raised {e!r} unexpectedly")

    def test_main_with_empty_file(self):
        # Создаём пустой CSV с заголовком и убеждаемся, что main() не падает
        with open('компоненты.csv', 'w', encoding='utf-8', newline='') as f:
            f.write('Компонент;Лицензия\n')
        try:
            main()
        except Exception as e:
            self.fail(f"main() raised {e!r} on empty data")

    def test_main_with_mixed_licenses(self):
        # Смесь допустимых и требующих проверки лицензий
        with open('компоненты.csv', 'w', encoding='utf-8', newline='') as f:
            f.write('Компонент;Лицензия\n')
            f.write('A;MIT\n')
            f.write('B;GPL-3.0\n')
            f.write('C;Apache-2.0\n')
            f.write('D;Unknown\n')
        try:
            main()
        except Exception as e:
            self.fail(f"main() raised {e!r} on mixed licenses")

if __name__ == "__main__":
    unittest.main()", "path": "/workspace/project/test_проверка_лицензий.py"}

